The most commonly missed detail in error handling design isn't the status code — it's **the response body structure.** Every team invents their own error schema: some use `{"error": "..."}`, some use `{"message": "...", "code": 42}`, some use `{"success": false, "reason": "..."}`. Clients that consume multiple services write custom parsing for each. Spring 6 solves this with built-in support for RFC 7807 `ProblemDetail`.

`ProblemDetail` defines five standard fields: `type` (a URI identifying the problem category), `title` (human-readable summary), `status` (HTTP status code), `detail` (specific description), and `instance` (URI of the specific occurrence). Any additional fields — like a list of validation errors — go in extension properties.

```java
@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(ResourceNotFoundException.class)
    public ProblemDetail handleNotFound(ResourceNotFoundException ex, HttpServletRequest request) {
        ProblemDetail problem = ProblemDetail
            .forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());
        problem.setType(URI.create("https://api.example.com/errors/not-found"));
        problem.setInstance(URI.create(request.getRequestURI()));
        return problem;
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ProblemDetail handleValidation(MethodArgumentNotValidException ex) {
        ProblemDetail problem = ProblemDetail.forStatus(HttpStatus.UNPROCESSABLE_ENTITY);
        // Extension property — list field violations for client display
        problem.setProperty("violations",
            ex.getBindingResult().getFieldErrors().stream()
                .map(e -> Map.of("field", e.getField(), "message", e.getDefaultMessage()))
                .toList());
        return problem;
    }
}
```

**`@RestControllerAdvice` ensures `ProblemDetail` is serialized to JSON** without an explicit `@ResponseBody` on each handler method. The `violations` extension property gives frontend teams the field-level errors they need to display inline next to form fields — without parsing free-text messages. For Spring Boot 3.x, enabling `spring.mvc.problemdetails.enabled=true` also makes the default Spring MVC exception handlers (like `NoResourceFoundException`) automatically return `ProblemDetail` instead of the legacy Whitelabel Error Page.

**One additional Spring Boot 3.x detail:** setting `spring.mvc.problemdetails.enabled=true` in `application.properties` makes all of Spring MVC's built-in exception handlers — like `NoResourceFoundException` and `HttpRequestMethodNotSupportedException` — automatically return `ProblemDetail` responses instead of the Whitelabel HTML error page. This gives you RFC 7807-compliant error bodies for framework exceptions without writing a handler for each one.

// Option A: extend ErrorResponseException for per-exception ProblemDetail
public class OrderNotFoundException extends ErrorResponseException {
    public OrderNotFoundException(String orderId) {
        super(HttpStatus.NOT_FOUND, problemFor(orderId), null);
    }
    private static ProblemDetail problemFor(String orderId) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(
            HttpStatus.NOT_FOUND,
            "Order %s was not found.".formatted(orderId));
        pd.setType(URI.create("https://errors.api.acme.com/resource/not-found"));
        pd.setTitle("Resource not found");
        pd.setProperty("code", "ORDER_NOT_FOUND");
        pd.setProperty("resourceType", "order");
        pd.setProperty("resourceId", orderId);
        return pd;
    }
}

// Throw from any controller or service — Spring translates automatically:
@RestController @RequestMapping("/v1/orders")
class OrderController {
    @GetMapping("/{id}")
    OrderDto get(@PathVariable String id) {
        return orders.findById(id)
            .orElseThrow(() -> new OrderNotFoundException(id));
    }
}

// Option B: implement ErrorResponse directly (more control, no inheritance)
public class InsufficientFundsException
        extends RuntimeException implements ErrorResponse {
    private final ProblemDetail body;
    public InsufficientFundsException(BigDecimal balance, BigDecimal required) {
        super("Insufficient funds");
        this.body = ProblemDetail.forStatusAndDetail(HttpStatus.PAYMENT_REQUIRED,
            "Balance %s, required %s".formatted(balance, required));
        body.setType(URI.create("https://errors.api.acme.com/billing/insufficient-funds"));
        body.setTitle("Insufficient funds");
        body.setProperty("code", "BILLING_INSUFFICIENT_FUNDS");
        body.setProperty("balance",  balance.toPlainString());
        body.setProperty("required", required.toPlainString());
    }
    @Override public HttpStatusCode getStatusCode() { return HttpStatus.PAYMENT_REQUIRED; }
    @Override public ProblemDetail getBody()        { return body; }
}

@RestControllerAdvice
class GlobalErrorHandler extends ResponseEntityExceptionHandler {

    // 1. Any domain exception implementing ErrorResponse is already handled
    //    by Spring; but we intercept to add cross-cutting extensions (traceId).
    @ExceptionHandler(ErrorResponse.class)
    ResponseEntity<ProblemDetail> handleErrorResponse(ErrorResponse ex,
                                                      HttpServletRequest req) {
        ProblemDetail pd = ex.getBody();
        pd.setInstance(URI.create(req.getRequestURI()));
        pd.setProperty("traceId", MDC.get("traceId"));
        return ResponseEntity.status(ex.getStatusCode())
            .headers(ex.getHeaders()).body(pd);
    }

    // 2. Override Spring's validation translation to emit field-level errors
    @Override
    protected ResponseEntity<Object> handleMethodArgumentNotValid(
            MethodArgumentNotValidException ex, HttpHeaders h, HttpStatusCode st,
            WebRequest req) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,
            "%d field(s) failed validation.".formatted(ex.getFieldErrorCount()));
        pd.setType(URI.create("https://errors.api.acme.com/validation/invalid-request"));
        pd.setTitle("Validation failed");
        pd.setProperty("code", "VALIDATION_FAILED");
        pd.setProperty("traceId", MDC.get("traceId"));
        pd.setProperty("errors", ex.getBindingResult().getFieldErrors().stream()
            .map(fe -> Map.of(
                "field",   fe.getField(),
                "code",    Optional.ofNullable(fe.getCode()).orElse("INVALID"),
                "message", fe.getDefaultMessage()))
            .toList());
        return ResponseEntity.badRequest()
            .contentType(MediaType.APPLICATION_PROBLEM_JSON).body(pd);
    }

    // 3. Bad JSON body — override Spring's translation
    @Override
    protected ResponseEntity<Object> handleHttpMessageNotReadable(
            HttpMessageNotReadableException ex, HttpHeaders h, HttpStatusCode st,
            WebRequest req) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,
            "Request body is malformed or unreadable.");
        pd.setType(URI.create("https://errors.api.acme.com/request/malformed-body"));
        pd.setTitle("Malformed request body");
        pd.setProperty("code", "BODY_MALFORMED");
        pd.setProperty("traceId", MDC.get("traceId"));
        return ResponseEntity.badRequest()
            .contentType(MediaType.APPLICATION_PROBLEM_JSON).body(pd);
    }

    // 4. Spring Security authentication and access-denied
    @ExceptionHandler({AuthenticationException.class})
    ResponseEntity<ProblemDetail> handleAuth(AuthenticationException ex) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(HttpStatus.UNAUTHORIZED,
            "Authentication is required or your token is invalid.");
        pd.setType(URI.create("https://errors.api.acme.com/auth/invalid-token"));
        pd.setTitle("Unauthorized");
        pd.setProperty("code", "AUTH_INVALID_TOKEN");
        pd.setProperty("traceId", MDC.get("traceId"));
        return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
            .header(HttpHeaders.WWW_AUTHENTICATE, "Bearer realm=\"api\"")
            .contentType(MediaType.APPLICATION_PROBLEM_JSON).body(pd);
    }

    // 5. Final safety net — never let a stack trace leak
    @ExceptionHandler(Throwable.class)
    ResponseEntity<ProblemDetail> handleUnexpected(Throwable ex) {
        log.error("unexpected", ex);
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(
            HttpStatus.INTERNAL_SERVER_ERROR,
            "An unexpected error occurred. Reference traceId to contact support.");
        pd.setType(URI.create("https://errors.api.acme.com/system/internal"));
        pd.setTitle("Internal server error");
        pd.setProperty("code", "INTERNAL_ERROR");
        pd.setProperty("traceId", MDC.get("traceId"));
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
            .contentType(MediaType.APPLICATION_PROBLEM_JSON).body(pd);
    }
}

public record CreateCustomerRequest(
    @NotBlank(message = "{customer.name.required}")
    @Size(max = 100)
    String name,

    @NotBlank
    @Email(message = "{customer.email.invalid}")
    String email,

    @Past(message = "{customer.birthDate.inPast}")
    LocalDate birthDate,

    @NotNull
    @Valid                                  // cascade into the nested object
    AddressDto address,

    @Size(min = 1, max = 5)
    List<@Valid PhoneDto> phones            // cascade into each element
) {}

public record AddressDto(
    @NotBlank String street,
    @NotBlank @Size(min = 2, max = 2) String countryCode,
    @Pattern(regexp = "\\d{5}(-\\d{4})?") String postalCode
) {}

// Controller — @Valid on the @RequestBody triggers MethodArgumentNotValidException
@RestController @RequestMapping("/v1/customers")
class CustomerController {
    @PostMapping
    CustomerDto create(@RequestBody @Valid CreateCustomerRequest req) {
        return service.create(req);
    }

    // @Validated on path/query params -> HandlerMethodValidationException (Spring 6.1+)
    @GetMapping
    Page<CustomerDto> list(
        @RequestParam(defaultValue = "0") @Min(0) int page,
        @RequestParam(defaultValue = "20") @Min(1) @Max(100) int size) {
        return service.list(page, size);
    }
}

@RestControllerAdvice
class ValidationErrorHandler extends ResponseEntityExceptionHandler {

    // 1. @Valid on @RequestBody / @ModelAttribute
    @Override
    protected ResponseEntity<Object> handleMethodArgumentNotValid(
            MethodArgumentNotValidException ex, HttpHeaders h, HttpStatusCode st,
            WebRequest req) {
        List<Map<String, Object>> errors = Stream.concat(
                ex.getBindingResult().getFieldErrors().stream().map(this::fieldError),
                ex.getBindingResult().getGlobalErrors().stream().map(this::globalError))
            .toList();
        return responseFor(errors);
    }

    // 2. @Validated on controller method parameters (Spring 6.1+)
    @Override
    protected ResponseEntity<Object> handleHandlerMethodValidationException(
            HandlerMethodValidationException ex, HttpHeaders h, HttpStatusCode st,
            WebRequest req) {
        List<Map<String, Object>> errors = ex.getAllValidationResults().stream()
            .flatMap(r -> r.getResolvableErrors().stream().map(err -> Map.of(
                "field",   r.getMethodParameter().getParameterName(),
                "code",    defaultCode(err.getCodes()),
                "message", err.getDefaultMessage(),
                "rejectedValue", scrub(r.getArgument())
            )))
            .toList();
        return responseFor(errors);
    }

    // 3. @Validated on service bean -> ConstraintViolationException
    @ExceptionHandler(ConstraintViolationException.class)
    ResponseEntity<Object> handleConstraintViolation(ConstraintViolationException ex) {
        List<Map<String, Object>> errors = ex.getConstraintViolations().stream()
            .map(v -> Map.of(
                "field",   lastNode(v.getPropertyPath()),
                "code",    v.getConstraintDescriptor().getAnnotation()
                            .annotationType().getSimpleName()
                            .toUpperCase(Locale.ROOT),          // NotBlank -> NOTBLANK
                "message", v.getMessage(),
                "rejectedValue", scrub(v.getInvalidValue())
            ))
            .toList();
        return responseFor(errors);
    }

    // ---- helpers ----
    private Map<String, Object> fieldError(FieldError fe) {
        return Map.of(
            "field",         fe.getField(),
            "code",          Optional.ofNullable(fe.getCode())
                              .map(c -> c.toUpperCase(Locale.ROOT)).orElse("INVALID"),
            "message",       fe.getDefaultMessage(),
            "rejectedValue", scrub(fe.getRejectedValue())
        );
    }

    private Map<String, Object> globalError(ObjectError oe) {
        return Map.of(
            "field",   "_global",
            "code",    defaultCode(oe.getCodes()),
            "message", oe.getDefaultMessage()
        );
    }

    private ResponseEntity<Object> responseFor(List<Map<String, Object>> errors) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,
            "%d field(s) failed validation.".formatted(errors.size()));
        pd.setType(URI.create("https://errors.api.acme.com/validation/invalid-request"));
        pd.setTitle("Validation failed");
        pd.setProperty("code", "VALIDATION_FAILED");
        pd.setProperty("traceId", MDC.get("traceId"));
        pd.setProperty("errors", errors);
        return ResponseEntity.badRequest()
            .contentType(MediaType.APPLICATION_PROBLEM_JSON).body(pd);
    }

    private String defaultCode(String[] codes) {
        if (codes == null || codes.length == 0) return "INVALID";
        return codes[0].split("\\.")[0].toUpperCase(Locale.ROOT);   // NotBlank.name -> NOTBLANK
    }

    private String lastNode(Path p) {
        String last = null;
        for (Path.Node n : p) last = n.getName();
        return last;
    }

    // Scrub PII from rejectedValue before returning to client
    private Object scrub(Object value) {
        if (value == null) return null;
        String s = value.toString();
        if (s.contains("@"))   return "***@***";        // email
        if (s.matches("\\d{13,19}")) return "****";     // card/acct numbers
        return s.length() > 64 ? s.substring(0, 64) + "\u2026" : s;
    }
}
